  'chat.designToolbox.prompt.skillInstruction': '╪º╪¿╪¬╪»╪º ╪¿┘ç╪¬╪▒█î┘å ┘ç╪»┘ü ╪¿╪╣╪»█î ╪▒╪º ╪¬╪╣█î█î┘å ┌⌐┘å█î╪»╪î ╪│┘╛╪│ █î┌⌐ ┘╛╪º╪│ ┘à╪┤╪«╪╡ ╪▒╪º ╪¬┌⌐┘à█î┘ä ┌⌐┘å█î╪». ╪º┌»╪▒ ╪¿┘ç ╪»╪º╪▒╪º█î█îΓÇî┘ç╪º █î╪º API┘ç╪º█î ╪«╪º╪▒╪¼█î ┘ê╪º╪¿╪│╪¬┘ç ╪º╪│╪¬╪î █î┌⌐ ╪¡╪º┘ä╪¬ ╪¼╪º█î┌»╪▓█î┘å ┘é╪º╪¿┘äΓÇî╪º╪¼╪▒╪º ╪º╪▒╪º╪ª┘ç ╪»┘ç█î╪» █î╪º ╪¿█î╪º┘å ┌⌐┘å█î╪» ┌å┘ç ┌å█î╪▓█î ╪¿╪º█î╪» ╪º╪▓ ╪│┘ê█î ┘à┘å ┘ü╪▒╪º┘ç┘à ╪┤┘ê╪».',
