  'chat.designToolbox.prompt.mcpResource': '╪¿╪▒╪º█î ┌»╪º┘à ╪╖╪▒╪º╪¡█î ╪¿╪╣╪»█î╪î ╪º█î┘å ┘é╪º╪¿┘ä█î╪¬ MCP ╪▒╪º ╪¬╪▒╪¼█î╪¡ ╪»┘ç█î╪». ┘ç┘å┌»╪º┘à█î ┌⌐┘ç ╪¿┘ç ╪»╪º╪▒╪º█î█îΓÇî┘ç╪º█î ╪«╪º╪▒╪¼█î╪î ╪╢╪¿╪╖ ┘ê╪¿╪î ╪¬┘ê┘ä█î╪» ╪¬╪╡┘ê█î╪▒/┘ê█î╪»╪ª┘ê █î╪º ╪»╪º╪»┘ç ┘å█î╪º╪▓ ╪º╪│╪¬╪î ╪º╪¿╪¬╪»╪º ╪¬╪╡┘à█î┘à ╪¿┌»█î╪▒█î╪» ╪ó█î╪º ┘à█îΓÇî╪¬┘ê╪º┘å╪» ┌⌐╪º╪▒ ╪▒╪º ╪º┘å╪¼╪º┘à ╪»┘ç╪»╪î ╪│┘╛╪│ █î┌⌐ ╪¿╪▒┘å╪º┘à┘ç ┘é╪º╪¿┘äΓÇî╪º╪¼╪▒╪º ╪º╪▒╪º╪ª┘ç ╪»┘ç█î╪».',
  'chat.designToolbox.prompt.mcpTemplateResource': '╪º█î┘å MCP █î┌⌐ ┘é╪º┘ä╪¿ ┘é╪º╪¿┘äΓÇî┘╛█î┌⌐╪▒╪¿┘å╪»█î ╪º╪│╪¬. ╪º┌»╪▒ ┘à┘ü█î╪»╪¬╪▒█î┘å ╪º╪¿╪▓╪º╪▒ ╪¿╪▒╪º█î ╪º█î┘å ┌»╪º┘à ╪╖╪▒╪º╪¡█î ╪º╪│╪¬╪î ╪º╪¿╪¬╪»╪º ╪▒╪º┘çΓÇî╪º┘å╪»╪º╪▓█î ╪▒╪º ╪▒╪º┘ç┘å┘à╪º█î█î ┌⌐┘å█î╪»╪¢ ╪º┌»╪▒ █î┌⌐ ╪¼╪º█î┌»╪▓█î┘å ┘╛█î┌⌐╪▒╪¿┘å╪»█îΓÇî╪┤╪»┘ç ┘ê╪¼┘ê╪» ╪»╪º╪▒╪»╪î ╪¿╪º ┘ç┘à╪º┘å ╪¼╪º█î┌»╪▓█î┘å ╪º╪»╪º┘à┘ç ╪»┘ç█î╪».',
